/**
 * DevSpec Pi — installing the launcher.
 *
 * The rocket button in DevSpec opens your agent through a machine-level launcher
 * that owns `devspec://`. Until now only the Cursor plugin shipped it, so a Pi-only
 * machine had a launch button that did nothing (ADR 8ced3e43, item 27b53001).
 *
 * Pi carries its own copy under `launcher/` and installs it the first time a
 * session starts. The copy is generated by the launcher repo's release step and
 * pinned by digest in LAUNCHER-MANIFEST.json — never edited here. `launcher.test.ts`
 * fails if anyone hand-edits it.
 *
 * Two rules this module exists to keep:
 *
 * - **Never downgrade.** Several plugins may carry the launcher and each installs on
 *   its own start-up, so `ensureLauncherInstalled` compares versions and leaves a
 *   newer launcher alone. Without that, whichever agent started last would win.
 * - **Never break the session.** A launcher that cannot install costs you a rocket
 *   button; an exception thrown during session start costs you the agent. So every
 *   failure is swallowed to a debug line, and the common path is one file read.
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { debugRemote as debug } from "./core/debug.ts";

/** The vendored copy that ships with this plugin. */
const LAUNCHER_DIR = fileURLToPath(new URL("../launcher", import.meta.url));

export async function installBundledLauncher(): Promise<string> {
	const manifestPath = join(LAUNCHER_DIR, "LAUNCHER-MANIFEST.json");
	const { readFile } = await import("node:fs/promises");
	const { version } = JSON.parse(await readFile(manifestPath, "utf8")) as { version: string };
	const { ensureLauncherInstalled } = await import(join(LAUNCHER_DIR, "ensure.mjs"));
	const result = ensureLauncherInstalled({ sourceDir: LAUNCHER_DIR, version });
	return result.outcome as string;
}

export default function (pi: ExtensionAPI) {
	pi.on("session_start", async () => {
		try {
			const outcome = await installBundledLauncher();
			debug("launcher install", {
				installed: outcome === "installed",
				keptNewer: outcome === "kept_newer",
				current: outcome === "current",
			});
		} catch {
			// Vendored copy missing, home unwritable, sandbox — none of it is worth
			// interrupting someone's session over.
			debug("launcher install failed", { errorPresent: true });
		}
	});
}
